/* ===================== BÀI 35 · Chế độ maximum và điều khiển bus ===================== */
/* Bài 35 · Chế độ maximum và điều khiển bus (AMTS-EMB-002-M09-L03, X86-035) — sinh bởi tools/author/mpu8086/l35.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P35=[{"label": "Ví dụ: đọc bộ nhớ 101 → MRDC, ghi 110", "code": "; Ví dụ 1: đọc và ghi bộ nhớ ở chế độ maximum\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DB      5AH\ny       DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, x                   ; S2 S1 S0 = 101 → 8288 bật MRDC\n        ADD     AL, 1                   ; không có chu kỳ bus dữ liệu\n        MOV     y, AL                   ; S2 S1 S0 = 110 → AMWC, MWTC\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Công cụ chu kỳ bus (Hình 35.1) mở ở chế độ maximum. MOV AL, x: S2 S1 S0 = 101 → 8288 bật MRDC; MOV y, AL: 110 → AMWC từ T2 rồi MWTC từ T3. Trong dạng sóng, S2 S1 S0 về 111 ở T3. Đổi sang minimum để thấy cùng chu kỳ đó dùng RD, WR, M/IO. Đoán trước: ADD AL, 1 có chu kỳ bus dữ liệu không? Đáp án không."}, {"label": "Ví dụ: IN, OUT → IORC, IOWC", "code": "; Ví dụ 2: IN, OUT → IORC, IOWC\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nr       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, 0306H               ; cổng giả định (chẵn)\n        IN      AX, DX                  ; S2 S1 S0 = 001: một chu kỳ word\n        MOV     r, AX\n        MOV     AL, 55H\n        OUT     DX, AL                  ; S2 S1 S0 = 010: AIOWC rồi IOWC\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "IN AX, DX ở cổng chẵn 0306h (giả định): một chu kỳ word, S2 S1 S0 = 001 → IORC; cổng chưa gắn thiết bị nên đọc FFFFh (quy ước của trình mô phỏng). OUT DX, AL: 010 → AIOWC rồi IOWC, byte 55h trên D7–D0. Đoán trước: mã S2 S1 S0 của OUT là gì? Đáp án 010."}, {"label": "Ví dụ: ghi sớm AMWC, ghi thường MWTC", "code": "; Ví dụ 3: lệnh ghi sớm AMWC và lệnh ghi thường MWTC\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nw       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234H\n        MOV     w, AX                   ; ghi bộ nhớ qua DS\n        PUSH    AX                      ; ghi vào ngăn xếp qua SS\n        POP     BX                      ; đọc ngăn xếp\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ba chu kỳ: ghi w qua DS (110), PUSH ghi ngăn xếp qua SS (110, S4 S3 = 01), POP đọc ngăn xếp (101). Bấm từng hàng để so AMWC và MWTC. Với bộ nhớ chậm, đổi số Tw: S2 S1 S0 về 111 ở Tw cuối. Đoán trước: PUSH AX ghi vào địa chỉ vật lý nào? Đáp án 0722Eh."}, {"label": "Bẫy: INT n không có chu kỳ INTA", "code": "; Ví dụ 4 (bẫy): INT n là ngắt mềm, không có chu kỳ INTA\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nvec     DW      xuly                    ; độ lệch của chương trình phục vụ\ndem     DB      0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, vec\n        XOR     AX, AX\n        MOV     ES, AX                  ; ES = 0000h: bảng vectơ ngắt\n        MOV     ES:[0180H], BX          ; vectơ 60h, phần IP (60h x 4)\n        MOV     ES:[0182H], CS          ; vectơ 60h, phần CS\n        INT     60H                     ; đọc vectơ, cất FLAGS, CS, IP\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nxuly:\n        INC     dem                     ; chương trình phục vụ ngắt 60h\n        IRET\n        END     MAIN\n", "input": "", "note": "Bẫy: INT 60h là ngắt mềm. Bảng chu kỳ bus không có mã 000 (INTA): CPU đọc vectơ ở 00180h, 00182h bằng chu kỳ đọc bộ nhớ (101) và cất FLAGS, CS, IP vào ngăn xếp (110). INTA chỉ có khi thiết bị ngắt qua chân INTR (chương 11). Thứ tự các chu kỳ trong lệnh INT lấy theo trình mô phỏng. Đoán trước: lệnh INT 60h có mấy chu kỳ bus dữ liệu? Đáp án 5."}, {"label": "Lỗi: dùng HLT để kết thúc chương trình DOS", "code": "; Ví dụ 5 (lỗi): dùng HLT để kết thúc chương trình DOS\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DB      7\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        INC     x                       ; đọc rồi ghi x\n        HLT                             ; chu kỳ dừng: S2 S1 S0 = 011\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: HLT không trả quyền cho DOS. CPU vào chu kỳ dừng (S2 S1 S0 = 011, 8288 không bật lệnh nào) và chờ ngắt; trên PC thật, ngắt bộ định thời (khoảng 18,2 lần/giây) đánh thức CPU và nó chạy tiếp các byte sau HLT: kết quả không xác định. Trình mô phỏng coi HLT là kết thúc nên chương trình có vẻ đúng. Sửa: MOV AX, 4C00h / INT 21h. Đoán trước: sau INC x, x bằng bao nhiêu? Đáp án 08h."}, {"label": "Ví dụ: tiền tố LOCK bao cả lệnh XCHG", "code": "; Ví dụ 6: tiền tố LOCK giữ bus suốt lệnh XCHG\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DB      0                       ; cờ dùng chung: 0 = rảnh\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 1\n        LOCK    XCHG AL, co             ; đọc rồi ghi co, chân LOCK thấp\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "LOCK XCHG AL, co: mã máy F0 86 06 00 00, 25 chu kỳ (17 + EA 6 + LOCK 2). Ở chế độ maximum, chân LOCK thấp trong cả hai chu kỳ bus (đọc 00h, ghi 01h): không bộ xử lý nào chen vào giữa. Ở chế độ minimum không có chân LOCK. Đoán trước: sau lệnh, AL bằng bao nhiêu? Đáp án 00h (giá trị cũ của co: cờ đang rảnh)."}];
const sim35=makeX86Sim(document.getElementById("x86-l35"),{id:"s35",presets:P35,file:"BAI35.ASM"});
makeX86Ex(document.getElementById("ex-l35"),sim35,[{"t": "Giải mã S2 S1 S0 như 8288", "d": "Nhập 3 phím 0 hoặc 1: lần lượt S2, S1, S0. Ghi giá trị S2 S1 S0 (0–7) vào biến ma rồi in tên lệnh mà bộ điều khiển bus 8288 bật cho trạng thái đó, đúng chuỗi trong bảng bang của code mẫu (INTA, IORC, AIOWC IOWC, KHONG, MRDC, MRDC, AMWC MWTC, KHONG theo thứ tự 0–7; KHONG là không bật lệnh nào).", "start": "; Bài tập 1: giải mã S2 S1 S0 như 8288\n; Nhập 3 chữ số 0/1: S2, S1, S0. In tên lệnh 8288 bật\n; (chuỗi trong bảng), ghi giá trị 0-7 vào biến ma.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nma      DB      ?                       ; S2 S1 S0 dạng số 0-7\nt0      DB      'INTA$'\nt1      DB      'IORC$'\nt2      DB      'AIOWC IOWC$'\nt3      DB      'KHONG$'\nt4      DB      'MRDC$'\nt6      DB      'AMWC MWTC$'\nbang    DW      t0, t1, t2, t3, t4, t4, t6, t3\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; Viết code ở đây: đọc 3 phím, tính ma,\n; lấy địa chỉ chuỗi trong bang rồi in bằng hàm 09h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "101", "out": "MRDC", "mem": [{"at": "ma", "bytes": [5]}]}, {"in": "000", "out": "INTA", "mem": [{"at": "ma", "bytes": [0]}]}, {"in": "001", "out": "IORC", "mem": [{"at": "ma", "bytes": [1]}]}, {"in": "010", "out": "AIOWC IOWC", "mem": [{"at": "ma", "bytes": [2]}]}, {"in": "011", "out": "KHONG", "mem": [{"at": "ma", "bytes": [3]}]}, {"in": "100", "out": "MRDC", "mem": [{"at": "ma", "bytes": [4]}]}, {"in": "110", "out": "AMWC MWTC", "mem": [{"at": "ma", "bytes": [6]}]}, {"in": "111", "out": "KHONG", "mem": [{"at": "ma", "bytes": [7]}]}]}, {"t": "Theo dõi hàng đợi qua QS", "d": "Nhập một dãy mã trạng thái hàng đợi QS1 QS0 (mỗi phím 0, 1, 2 hoặc 3, tối đa 20 phím), kết thúc bằng Enter. Mã 1: byte đầu của một lệnh được lấy khỏi hàng đợi; mã 3: byte tiếp theo được lấy; mã 2: hàng đợi bị xóa; mã 0: không có gì. Ghi số mã 1 vào soLenh, số byte đã lấy (mã 1 và 3) vào soByte, số mã 2 vào soXoa. Code mẫu đã có phần in ba số, cách nhau dấu cách.", "start": "; Bài tập 2: theo dõi hàng đợi lệnh qua QS1 QS0\n; Nhập dãy mã QS (0-3), kết thúc bằng Enter. Đếm:\n; soLenh = số mã 1, soByte = số mã 1 và 3, soXoa = số mã 2.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoLenh  DB      0                       ; số lệnh bắt đầu (mã 1)\nsoByte  DB      0                       ; số byte lấy khỏi hàng đợi (mã 1, 3)\nsoXoa   DB      0                       ; số lần xóa hàng đợi (mã 2)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 13                  ; Enter: hết dãy\n        JE      inkq\n; Viết code ở đây: cập nhật 3 bộ đếm theo mã trong AL\n        JMP     doc\ninkq:\n        MOV     AL, soLenh              ; in \"soLenh soByte soXoa\"\n        CALL    IN1\n        MOV     AL, soByte\n        CALL    IN1\n        MOV     AL, soXoa\n        CALL    IN1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; IN1: in AL (0-255) dạng thập phân, rồi một dấu cách\nIN1:\n        XOR     AH, AH\n        CALL    INSO\n        MOV     AH, 02H\n        MOV     DL, ' '\n        INT     21H\n        RET\n; INSO: in AX ở dạng thập phân\nINSO:\n        MOV     BX, 10\n        XOR     CX, CX\nis1:\n        XOR     DX, DX\n        DIV     BX\n        PUSH    DX\n        INC     CX\n        TEST    AX, AX\n        JNZ     is1\n        MOV     AH, 02H\nis2:\n        POP     DX\n        ADD     DL, '0'\n        INT     21H\n        LOOP    is2\n        RET\n        END     MAIN\n", "tests": [{"in": "1313", "out": "2 4 0", "mem": [{"at": "soLenh", "bytes": [2]}, {"at": "soByte", "bytes": [4]}, {"at": "soXoa", "bytes": [0]}]}, {"in": "1", "out": "1 1 0", "mem": [{"at": "soLenh", "bytes": [1]}, {"at": "soByte", "bytes": [1]}, {"at": "soXoa", "bytes": [0]}]}, {"in": "13021", "out": "2 3 1", "mem": [{"at": "soLenh", "bytes": [2]}, {"at": "soByte", "bytes": [3]}, {"at": "soXoa", "bytes": [1]}]}, {"in": "0000", "out": "0 0 0", "mem": [{"at": "soLenh", "bytes": [0]}, {"at": "soByte", "bytes": [0]}, {"at": "soXoa", "bytes": [0]}]}, {"in": "13332133", "out": "2 7 1", "mem": [{"at": "soLenh", "bytes": [2]}, {"at": "soByte", "bytes": [7]}, {"at": "soXoa", "bytes": [1]}]}, {"in": "2222", "out": "0 0 4", "mem": [{"at": "soLenh", "bytes": [0]}, {"at": "soByte", "bytes": [0]}, {"at": "soXoa", "bytes": [4]}]}, {"in": "10303132013331330013", "out": "5 14 1", "mem": [{"at": "soLenh", "bytes": [5]}, {"at": "soByte", "bytes": [14]}, {"at": "soXoa", "bytes": [1]}]}]}, {"t": "Thống kê trạng thái nhanh hơn", "d": "Nhập một dãy chữ số 0–7 (mỗi chữ số là một mã S2 S1 S0 đọc được trên bus, tối đa 16 phím), kết thúc bằng Enter. Ghi vào mảng dem (8 byte) số lần gặp từng mã: dem[k] là số lần gặp k. Code mẫu đúng nhưng so sánh lần lượt 8 trường hợp nên chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: thống kê trạng thái bus nhanh hơn\n; Nhập dãy chữ số 0-7 (mã S2 S1 S0), kết thúc bằng Enter.\n; dem[k] = số lần gặp mã k. Bản này đúng nhưng chậm.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      8 DUP(0)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        LEA     SI, dem\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 13\n        JE      xong\n        CMP     AL, '0'\n        JNE     m1\n        INC     BYTE PTR [SI]\n        JMP     doc\nm1:     CMP     AL, '1'\n        JNE     m2\n        INC     BYTE PTR [SI+1]\n        JMP     doc\nm2:     CMP     AL, '2'\n        JNE     m3\n        INC     BYTE PTR [SI+2]\n        JMP     doc\nm3:     CMP     AL, '3'\n        JNE     m4\n        INC     BYTE PTR [SI+3]\n        JMP     doc\nm4:     CMP     AL, '4'\n        JNE     m5\n        INC     BYTE PTR [SI+4]\n        JMP     doc\nm5:     CMP     AL, '5'\n        JNE     m6\n        INC     BYTE PTR [SI+5]\n        JMP     doc\nm6:     CMP     AL, '6'\n        JNE     m7\n        INC     BYTE PTR [SI+6]\n        JMP     doc\nm7:     INC     BYTE PTR [SI+7]\n        JMP     doc\nxong:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "5051", "mem": [{"at": "dem", "bytes": [1, 1, 0, 0, 0, 2, 0, 0]}]}, {"in": "7777777777777777", "mem": [{"at": "dem", "bytes": [0, 0, 0, 0, 0, 0, 0, 16]}]}, {"in": "0123456701234567", "mem": [{"at": "dem", "bytes": [2, 2, 2, 2, 2, 2, 2, 2]}]}, {"in": "5", "mem": [{"at": "dem", "bytes": [0, 0, 0, 0, 0, 1, 0, 0]}]}, {"in": "6666555544447777", "mem": [{"at": "dem", "bytes": [0, 0, 0, 0, 4, 4, 4, 4]}]}, {"in": "7070707070707070", "mem": [{"at": "dem", "bytes": [8, 0, 0, 0, 0, 0, 0, 8]}]}], "perf": {"cycles": 1900, "bytes": 36}}]);
makeX86Bus(document.getElementById("bus-l35"),{presets:[Object.assign({},P35[0],{"mode": "max"}),Object.assign({},P35[1],{"mode": "max"}),Object.assign({},P35[2],{"mode": "max"}),Object.assign({},P35[3],{"mode": "max"}),Object.assign({},P35[4],{"mode": "max"}),Object.assign({},P35[5],{"mode": "max"})],modes:["max", "min"]});

makeQuiz("quiz35","score35",[{"q": "Ở chế độ maximum, 8288 thấy S2 S1 S0 = 110. Lệnh bus nào được bật?", "o": ["AMWC từ T2 rồi MWTC từ T3 (ghi bộ nhớ)", "MRDC từ T2 cho tới hết T3 (đọc bộ nhớ)", "AIOWC rồi IOWC (một chu kỳ ghi cổng I/O)", "INTA, vì CPU đang chấp nhận một ngắt phần cứng"], "a": 0, "e": "110 là ghi bộ nhớ: 8288 bật lệnh ghi sớm AMWC rồi lệnh ghi thường MWTC. 101 mới là đọc bộ nhớ (MRDC), 010 là ghi I/O, 000 là INTA."}, {"q": "Hệ 8086 chế độ maximum chạy đoạn code sau. Chu kỳ bus của lệnh IN có S2 S1 S0 bằng bao nhiêu và 8288 bật lệnh nào?<pre class=\"mp-asm\">        MOV     DX, 0306H\n        IN      AL, DX<\/pre>", "o": ["101, bật MRDC", "010, bật IOWC", "000, bật INTA", "001, bật IORC"], "a": 3, "e": "IN là đọc cổng I/O: mã 001, lệnh IORC. Mã 101/MRDC là đọc bộ nhớ (như MOV AL, [BX]); 010 là ghi cổng (OUT)."}, {"q": "Một sinh viên lấy sơ đồ bo 8086 minimum, chỉ đổi MN/MX xuống mass và giữ nguyên dây: chân 29 của 8086 vẫn nối vào chân ghi của RAM. Chuyện gì xảy ra?", "o": ["RAM vẫn ghi đúng vì chân 29 mang WR ở cả hai chế độ", "RAM được ghi hai lần mỗi chu kỳ vì có thêm AMWC", "Bo không khởi động được vì 8284A không có xung CLK", "Chân 29 giờ là LOCK chứ không phải WR: RAM ghi sai"], "a": 3, "e": "Ở chế độ maximum chân 24–31 đổi nghĩa: chân 29 là LOCK (chỉ thấp khi có tiền tố LOCK). Lệnh ghi bộ nhớ phải lấy MWTC hoặc AMWC từ 8288. 8284A không liên quan tới chế độ."}, {"q": "Đoạn code sau chạy trên hệ maximum (vectơ 60h đã trỏ tới chương trình phục vụ). Có chu kỳ bus nào mang S2 S1 S0 = 000 (INTA) không?<pre class=\"mp-asm\">        INT     60H<\/pre>", "o": ["Có: mọi lệnh INT đều có hai chu kỳ INTA để lấy số ngắt", "Không: ngắt mềm đọc vectơ bằng chu kỳ đọc bộ nhớ 101", "Có: một chu kỳ INTA, rồi CPU mới đọc vectơ ở 00180h", "Không: lệnh INT không dùng bus vì chạy hết trong CPU"], "a": 1, "e": "INTA chỉ có khi thiết bị ngắt qua chân INTR và CPU cần lấy số ngắt từ bus. INT 60h đã có số ngắt trong mã lệnh: CPU đọc vectơ (101) và cất FLAGS, CS, IP (110) — 5 chu kỳ bus dữ liệu (Ví dụ 4)."}, {"q": "8087 thấy QS1 QS0 ở các xung nhịp liên tiếp lần lượt là 01, 11, 11, 01. Kết luận nào đúng?", "o": ["Lệnh thứ nhất đã lấy 3 byte, rồi một lệnh mới bắt đầu", "Hàng đợi bị xóa hai lần nên 8087 phải nạp lại lệnh", "Bốn lệnh 1 byte lần lượt được lấy khỏi hàng đợi", "Không có byte nào được lấy vì 11 nghĩa là không thao tác"], "a": 0, "e": "01: byte đầu của một lệnh; 11: byte tiếp theo của lệnh đó; 01 lần nữa: lệnh mới. Mã 10 mới là xóa hàng đợi, 00 là không thao tác."}]);

